<?php
declare(strict_types=1);

/**
 * Import one device and its maintenance plan for Đội Carota Khí.
 * The thietbi_iso.stt value is generated by the database and links the plan.
 */

if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/config/constants.php';
require_once __DIR__ . '/includes/auth.php';
require_once __DIR__ . '/includes/permissions.php';
requireAuth();
if (!hasRole(ROLE_ADMIN)) {
    http_response_code(403);
    exit('Chỉ admin mới được chạy import này.');
}
header('Content-Type: text/html; charset=UTF-8');

mb_internal_encoding('UTF-8');

const SINGLE_IMPORT_MADV = 'KHI';
const SINGLE_IMPORT_CREATED_BY = 'import_kehoach_khi_mot_dong';
const SINGLE_IMPORT_UNITS = ['', 'KTKT', 'ĐVLTH', 'CNM', 'RDNGA', 'TV', 'XSCTBĐVL'];

function singleImportColumnLength(PDO $db, string $table, string $column): int
{
    $stmt = $db->prepare(
        'SELECT CHARACTER_MAXIMUM_LENGTH FROM INFORMATION_SCHEMA.COLUMNS
         WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?'
    );
    $stmt->execute([$table, $column]);
    return (int)($stmt->fetchColumn() ?: 0);
}

function singleImportFitLength(string $value, int $max): string
{
    return $max > 0 && strlen($value) > $max ? mb_strcut($value, 0, $max) : $value;
}

/**
 * @param array{apply: bool, year: int, name: string, code: string, serial: string, months: int[], note: string, main_unit: string, aux_unit: string} $input
 * @return array{summary: string[], plans: array<int, array{quarter: string, status: string}>}
 */
function runSingleImport(array $input): array
{
    $db = getDBConnection();
    $db->exec('SET NAMES latin1');

    $unitCheck = $db->prepare('SELECT COUNT(*) FROM donvi_iso WHERE TRIM(madv) = ?');
    $unitCheck->execute([SINGLE_IMPORT_MADV]);
    $warnings = [];
    if ((int)$unitCheck->fetchColumn() === 0) {
        $warnings[] = 'Mã đơn vị KHI chưa có trong donvi_iso.';
    }

    $deviceLengths = [];
    foreach (['mavt', 'tenvt', 'somay', 'model', 'mamay'] as $column) {
        $deviceLengths[$column] = singleImportColumnLength($db, 'thietbi_iso', $column);
    }
    $planLengths = [];
    foreach (['ten_thietbi', 'so_serial', 'ghi_chu'] as $column) {
        $planLengths[$column] = singleImportColumnLength($db, 'ke_hoach_bao_duong_dinh_ky_iso', $column);
    }

    $name = $input['name'];
    if ($input['serial'] !== '' && mb_stripos($name, $input['serial']) === false) {
        $name .= ' ' . $input['serial'];
    }
    $name = singleImportFitLength($name, $deviceLengths['tenvt']);
    $serial = singleImportFitLength(
        $input['serial'] !== '' ? $input['serial'] : ($input['code'] !== '' ? $input['code'] : 'N/A'),
        $deviceLengths['somay']
    );
    $model = '';
    $mavt = singleImportFitLength(
        $input['code'] !== '' ? $input['code'] : $input['serial'],
        $deviceLengths['mavt']
    );
    $mamay = singleImportFitLength(
        implode('-', array_filter([$mavt, $serial !== $mavt && $serial !== 'N/A' ? $serial : ''])),
        $deviceLengths['mamay']
    );

    $db->beginTransaction();
    try {
        $findDevice = $db->prepare(
            'SELECT stt, tenvt, madv FROM thietbi_iso WHERE mavt = ? AND somay = ? AND model = ? ORDER BY stt LIMIT 1'
        );
        $findDevice->execute([$mavt, $serial, $model]);
        $device = $findDevice->fetch(PDO::FETCH_ASSOC);
        $legacyDevice = false;
        if (!$device && $input['serial'] === '') {
            $findDevice->execute([$mavt, '', $model]);
            $device = $findDevice->fetch(PDO::FETCH_ASSOC);
            $legacyDevice = (bool)$device;
        }
        if ($device && ($device['tenvt'] !== $name || trim((string)$device['madv']) !== SINGLE_IMPORT_MADV)) {
            throw new RuntimeException('Ký mã hiệu/S/N đã thuộc thiết bị khác. Kiểm tra lại thông tin trước khi import.');
        }

        $apply = $input['apply'];
        $deviceCreated = false;
        if ($device) {
            $deviceId = (int)$device['stt'];
            if ($legacyDevice && $apply) {
                $db->prepare('UPDATE thietbi_iso SET somay = ?, mamay = ? WHERE stt = ?')
                    ->execute([$serial, $mamay, $deviceId]);
            }
        } elseif ($apply) {
            $deviceParams = [
                'mavt' => $mavt,
                'tenvt' => $name,
                'somay' => $serial,
                'model' => $model,
                'homay' => '',
                'dienap' => '',
                'thongtincb' => '',
                'loaidau' => '',
                'mucdau' => '',
                'madv' => SINGLE_IMPORT_MADV,
                'bdtime' => 0,
                'ngayktsd' => date('Y-m-d'),
                'tlkt' => '',
                'hosomay' => '',
                'mamay' => $mamay,
            ];
            $insertDevice = $db->prepare(
                'INSERT INTO thietbi_iso
                 (mavt, tenvt, somay, model, homay, dienap, thongtincb, loaidau, mucdau, madv, bdtime, ngayktsd, tlkt, hosomay, mamay)
                 VALUES (:mavt, :tenvt, :somay, :model, :homay, :dienap, :thongtincb, :loaidau, :mucdau, :madv, :bdtime, :ngayktsd, :tlkt, :hosomay, :mamay)'
            );
            $insertDevice->execute($deviceParams);
            $deviceId = (int)$db->lastInsertId();
            $deviceCreated = true;
        } else {
            $deviceId = 0;
            $deviceCreated = true;
        }

        $existingPlans = [];
        if ($deviceId > 0) {
            $findPlans = $db->prepare(
                'SELECT qui_1, qui_2, qui_3, qui_4
                 FROM ke_hoach_bao_duong_dinh_ky_iso
                 WHERE nam = ? AND thietbi_id = ?'
            );
            $findPlans->execute([$input['year'], $deviceId]);
            $existingPlans = $findPlans->fetchAll(PDO::FETCH_ASSOC);
        }
        $covered = [];
        foreach ($existingPlans as $existingPlan) {
            for ($quarter = 1; $quarter <= 4; $quarter++) {
                if (trim((string)($existingPlan["qui_$quarter"] ?? '')) !== '') {
                    $covered[$quarter] = true;
                }
            }
        }

        $planRows = [];
        $quarters = [];
        foreach ($input['months'] as $month) {
            $quarters[(int)ceil($month / 3)] = true;
        }
        $quarters = array_keys($quarters);
        sort($quarters);

        if ($quarters === []) {
            if ($existingPlans === []) {
                $planRows[] = ['quarter' => '-', 'status' => 'sẽ thêm kế hoạch không gắn quý'];
            } else {
                $planRows[] = ['quarter' => '-', 'status' => 'đã có kế hoạch trong năm, bỏ qua'];
            }
        } else {
            foreach ($quarters as $quarter) {
                if (isset($covered[$quarter])) {
                    $planRows[] = ['quarter' => (string)$quarter, 'status' => 'quý đã có, bỏ qua'];
                    continue;
                }
                $planRows[] = ['quarter' => (string)$quarter, 'status' => 'sẽ thêm'];
            }
        }

        $insertPlan = $db->prepare(
            'INSERT INTO ke_hoach_bao_duong_dinh_ky_iso
             (thietbi_id, nam, ten_thietbi, so_serial, nhomsc, qui_1, qui_2, qui_3, qui_4,
              donvi_lam_chinh, donvi_lam_phu, ghi_chu, created_by)
             VALUES (:thietbi_id, :nam, :ten_thietbi, :so_serial, :nhomsc, :qui_1, :qui_2, :qui_3, :qui_4,
                     :donvi_lam_chinh, :donvi_lam_phu, :ghi_chu, :created_by)'
        );
        $writePlan = static function (?int $quarter) use (
            $insertPlan,
            $deviceId,
            $input,
            $name,
            $serial,
            $planLengths
        ): void {
            $quartersBlank = ['qui_1' => '', 'qui_2' => '', 'qui_3' => '', 'qui_4' => ''];
            if ($quarter !== null) {
                $quartersBlank["qui_$quarter"] = 'TO';
            }
            $insertPlan->execute([
                'thietbi_id' => $deviceId,
                'nam' => $input['year'],
                'ten_thietbi' => singleImportFitLength($name, $planLengths['ten_thietbi']),
                'so_serial' => singleImportFitLength($serial, $planLengths['so_serial']),
                'nhomsc' => '',
                'qui_1' => $quartersBlank['qui_1'],
                'qui_2' => $quartersBlank['qui_2'],
                'qui_3' => $quartersBlank['qui_3'],
                'qui_4' => $quartersBlank['qui_4'],
                'donvi_lam_chinh' => $input['main_unit'],
                'donvi_lam_phu' => $input['aux_unit'],
                'ghi_chu' => singleImportFitLength($input['note'], $planLengths['ghi_chu']),
                'created_by' => SINGLE_IMPORT_CREATED_BY,
            ]);
        };

        if ($apply) {
            if ($quarters === []) {
                if ($existingPlans === []) {
                    $writePlan(null);
                    $planRows[0]['status'] = 'đã thêm kế hoạch không gắn quý';
                }
            } else {
                foreach ($quarters as $quarter) {
                    if (!isset($covered[$quarter])) {
                        $writePlan($quarter);
                        $covered[$quarter] = true;
                        foreach ($planRows as &$row) {
                            if ($row['quarter'] === (string)$quarter) {
                                $row['status'] = 'đã thêm';
                            }
                        }
                        unset($row);
                    }
                }
            }
        }

        if ($apply) {
            $db->commit();
        } else {
            $db->rollBack();
        }

        $summary = [
            $apply ? 'Đã ghi dữ liệu.' : 'Chạy thử - chưa ghi dữ liệu.',
            'Thiết bị DB STT: ' . ($deviceId > 0 ? (string)$deviceId : ($deviceCreated ? 'sẽ tự tăng khi ghi' : '')),
            'Thiết bị: ' . ($deviceCreated ? ($deviceId > 0 ? 'đã thêm mới' : 'sẽ thêm mới') : 'dùng lại thiết bị hiện có'),
            'Năm kế hoạch: ' . $input['year'],
            'Đơn vị chính/phụ: ' . ($input['main_unit'] !== '' ? $input['main_unit'] : '(trống)')
                . ' / ' . ($input['aux_unit'] !== '' ? $input['aux_unit'] : '(trống)'),
        ];
        foreach ($warnings as $warning) {
            $summary[] = 'Cảnh báo: ' . $warning;
        }
        return ['summary' => $summary, 'plans' => $planRows];
    } catch (Throwable $e) {
        if ($db->inTransaction()) {
            $db->rollBack();
        }
        throw $e;
    }
}

$escape = static fn(string $value): string => htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
if (empty($_SESSION['single_import_csrf'])) {
    $_SESSION['single_import_csrf'] = bin2hex(random_bytes(16));
}

$result = null;
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        if (!hash_equals($_SESSION['single_import_csrf'], (string)($_POST['csrf'] ?? ''))) {
            throw new RuntimeException('Phiên không hợp lệ, hãy tải lại trang.');
        }
        $year = filter_var($_POST['year'] ?? null, FILTER_VALIDATE_INT);
        if ($year === false || $year < 2000 || $year > 2100) {
            throw new RuntimeException('Năm kế hoạch phải từ 2000 đến 2100.');
        }
        $name = trim((string)($_POST['name'] ?? ''));
        $code = trim((string)($_POST['code'] ?? ''));
        $serial = trim((string)($_POST['serial'] ?? ''));
        $note = trim((string)($_POST['note'] ?? ''));
        $mainUnit = trim((string)($_POST['main_unit'] ?? 'KTKT'));
        $auxUnit = trim((string)($_POST['aux_unit'] ?? 'XSCTBĐVL'));
        if ($name === '') {
            throw new RuntimeException('Tên thiết bị là bắt buộc.');
        }
        if ($code === '' && $serial === '') {
            throw new RuntimeException('Nhập Ký mã hiệu hoặc Số S/N để nhận diện thiết bị.');
        }
        if (!in_array($mainUnit, SINGLE_IMPORT_UNITS, true) || !in_array($auxUnit, SINGLE_IMPORT_UNITS, true)) {
            throw new RuntimeException('Đơn vị chính hoặc đơn vị phụ không hợp lệ.');
        }

        $monthInput = trim((string)($_POST['months'] ?? ''));
        $months = [];
        if ($monthInput !== '') {
            foreach (preg_split('/[\s,;]+/', $monthInput) as $month) {
                if ($month === '' || !ctype_digit($month) || (int)$month < 1 || (int)$month > 12) {
                    throw new RuntimeException('Tháng phải là các số từ 1 đến 12, phân cách bằng dấu phẩy.');
                }
                $months[] = (int)$month;
            }
            $months = array_values(array_unique($months));
        }

        $mode = (string)($_POST['mode'] ?? '');
        if (!in_array($mode, ['preview', 'apply'], true)) {
            throw new RuntimeException('Thao tác không hợp lệ.');
        }
        $result = runSingleImport([
            'apply' => $mode === 'apply',
            'year' => $year,
            'name' => $name,
            'code' => $code,
            'serial' => $serial,
            'months' => $months,
            'note' => $note,
            'main_unit' => $mainUnit,
            'aux_unit' => $auxUnit,
        ]);
    } catch (Throwable $e) {
        $error = $e->getMessage();
    }
}
?>
<!DOCTYPE html>
<html lang="vi">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Import một thiết bị - Đội Carota Khí</title>
  <style>
    body { font-family: "Segoe UI", Arial, sans-serif; background: #f1f5f9; color: #1e293b; margin: 0; padding: 24px 16px; }
    main { max-width: 900px; margin: 0 auto; background: #fff; padding: 20px 24px; border-radius: 10px; border: 1px solid #e2e8f0; }
    h1 { margin-top: 0; font-size: 1.3rem; color: #312e81; }
    label { display: block; margin: 12px 0 4px; font-weight: 600; }
    input, select { width: min(100%, 420px); box-sizing: border-box; padding: 7px 10px; border: 1px solid #cbd5e1; border-radius: 6px; }
    button { padding: 8px 18px; border: 0; border-radius: 6px; color: #fff; font-weight: 600; cursor: pointer; margin: 12px 8px 0 0; }
    .preview { background: #4338ca; } .apply { background: #dc2626; }
    .note { color: #475569; font-size: .9rem; }
    .err { padding: 10px 14px; background: #fef2f2; border-left: 4px solid #dc2626; color: #991b1b; margin: 12px 0; }
    .result { padding: 12px 16px; background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 8px; }
    table { border-collapse: collapse; margin-top: 12px; }
    th, td { border: 1px solid #cbd5e1; padding: 6px 10px; text-align: left; }
    th { background: #e0e7ff; }
  </style>
</head>
<body>
<main>
  <h1>Import một thiết bị và kế hoạch bảo dưỡng</h1>
  <p class="note">Chỉ nhập một dòng. STT bảng không cần nhập: <b>thietbi_iso.stt</b> do DB tự tăng và được dùng làm liên kết với kế hoạch. Thiết bị thuộc đơn vị KHI; đơn vị chính/phụ của kế hoạch là KTKT / XSCTBĐVL.</p>
  <?php if ($error !== ''): ?><div class="err"><?= $escape($error) ?></div><?php endif; ?>

  <form method="post">
    <input type="hidden" name="csrf" value="<?= $escape($_SESSION['single_import_csrf']) ?>">
    <label for="year">Năm kế hoạch</label>
    <input type="number" id="year" name="year" min="2000" max="2100" value="<?= $escape((string)($_POST['year'] ?? 2026)) ?>" required>
    <label for="name">Tên thiết bị</label>
    <input type="text" id="name" name="name" value="<?= $escape((string)($_POST['name'] ?? '')) ?>" required>
    <label for="code">Ký mã hiệu</label>
    <input type="text" id="code" name="code" value="<?= $escape((string)($_POST['code'] ?? '')) ?>">
    <label for="serial">Số S/N</label>
    <input type="text" id="serial" name="serial" value="<?= $escape((string)($_POST['serial'] ?? '')) ?>">
    <label for="main_unit">Đơn vị làm chính</label>
    <select id="main_unit" name="main_unit">
      <?php foreach (SINGLE_IMPORT_UNITS as $unit): ?>
        <option value="<?= $escape($unit) ?>" <?= $unit === (string)($_POST['main_unit'] ?? 'KTKT') ? 'selected' : '' ?>>
          <?= $unit === '' ? '-- Chọn đơn vị --' : $escape($unit) ?>
        </option>
      <?php endforeach; ?>
    </select>
    <label for="aux_unit">Đơn vị làm phụ</label>
    <select id="aux_unit" name="aux_unit">
      <?php foreach (SINGLE_IMPORT_UNITS as $unit): ?>
        <option value="<?= $escape($unit) ?>" <?= $unit === (string)($_POST['aux_unit'] ?? 'XSCTBĐVL') ? 'selected' : '' ?>>
          <?= $unit === '' ? '-- Không có --' : $escape($unit) ?>
        </option>
      <?php endforeach; ?>
    </select>
    <label for="months">Tháng tô màu (1-12, có thể nhập nhiều tháng)</label>
    <input type="text" id="months" name="months" value="<?= $escape((string)($_POST['months'] ?? '')) ?>" placeholder="Ví dụ: 1, 7">
    <label for="note">Ghi chú</label>
    <input type="text" id="note" name="note" value="<?= $escape((string)($_POST['note'] ?? '')) ?>">
    <p class="note">Cần nhập Ký mã hiệu hoặc S/N. Tháng để trống nếu kế hoạch không gắn với quý. Đơn vị mặc định: KTKT / XSCTBĐVL.</p>
    <button class="preview" type="submit" name="mode" value="preview">Chạy thử</button>
    <button class="apply" type="submit" name="mode" value="apply"
            onclick="return confirm('Chỉ ghi thiết bị và kế hoạch này vào DB? Bạn đã chạy thử chưa?');">Ghi vào DB</button>
  </form>

  <?php if ($result !== null): ?>
    <section class="result">
      <?php foreach ($result['summary'] as $line): ?><p><?= $escape($line) ?></p><?php endforeach; ?>
      <table>
        <thead><tr><th>Quý</th><th>Kết quả</th></tr></thead>
        <tbody>
          <?php foreach ($result['plans'] as $plan): ?>
            <tr><td><?= $escape($plan['quarter']) ?></td><td><?= $escape($plan['status']) ?></td></tr>
          <?php endforeach; ?>
        </tbody>
      </table>
    </section>
  <?php endif; ?>
</main>
</body>
</html>
